mapper.select:
select baseinfo.prod_id prodId, baseinfo.prod_name prodName, substring(profit2.busi_date,1,7) reportDate, profit2.busi_date as busiDate from chb_prd_baseinfo baseinfo inner join ( SELECT distinct real_prd_id, busi_date FROM prd_profit profit
substring(busi_date,1,7) = #{reportDate,jdbcType=VARCHAR}
) profit2 on profit2.real_prd_id = baseinfo.prod_id
#{items,jdbcType=VARCHAR}

select profit.real_prd_id realPrdId, profit.subject_id subjectId, profit.subject_name subjectName, profit.ccy ccy, profit.current_amt currentAmt, profit.current_year_accumu_amt currentYearAccumuAmt, profit.busi_date busiDate from prd_profit profit
substring(profit.busi_date,1,7) = #{reportDate,jdbcType=VARCHAR}
AND profit.real_prd_id = #{prodId,jdbcType=VARCHAR}
ORDER BY profit.subject_id * 1
